import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type PokemonCounterProps = Record<string, any>;

const PokemonCounter: React.FC<PokemonCounterProps> = ({
  backgroundColor = "#70a0a0",
  transparentBackground = false,
  durationInSeconds = 5,
  startPrice = 0,
  endPrice = 9999,
  currencySymbol = "$",
  boxColor = "#ffffff",
  borderColor = "#202028",
  textColor = "#202028",
}) => {
  {/* Load Google Fonts */ }
  useFontLoader(["Press Start 2P"]);
  {/* End Load Google Fonts */ }

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;
  const durationInFrames = durationInSeconds * fps;

  // 1. Box Appearance Animation (Spring)
  const boxScale = spring({
    frame,
    fps,
    config: {
      damping: 15,
      mass: 1,
      stiffness: 120,
    },
  });

  // 2. Counter Animation (Linear Interpolation)
  // We stop the counter a bit before the end to let the result sit
  const countDuration = durationInFrames * 0.8;
  const currentCount = interpolate(frame, [0, countDuration], [startPrice, endPrice], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  // Format as integer for that retro feeling
  const displayCount = Math.floor(currentCount);

  // 3. Blinking Cursor (Waiting for input style)
  // Only shows up after counting is done
  const showCursor = frame > countDuration;
  const cursorOpacity = Math.floor(frame / 15) % 2 === 0 ? 1 : 0; // Blink every 15 frames

  // Dynamic Styles
  const containerStyle: React.CSSProperties = {
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    width: "100%",
    height: "100%",
    backgroundColor: finalBgColor,
    fontFamily: '"Press Start 2P", cursive',
  };

  // Pixel-art box style
  const boxWidth = Math.min(width * 0.8, 800);
  const borderSize = Math.max(4, width * 0.005);
  
  const boxStyle: React.CSSProperties = {
    backgroundColor: boxColor,
    border: `${borderSize}px solid ${borderColor}`,
    borderRadius: "4px", // slight roundness or 0 for strict retro
    padding: "40px",
    width: boxWidth,
    position: "relative",
    boxShadow: `8px 8px 0px rgba(0,0,0,0.2)`, // Retro drop shadow
    transform: `scale(${boxScale})`,
    display: "flex",
    flexDirection: "column",
    gap: "20px",
    transition: "none",
  };

  const textStyle: React.CSSProperties = {
    color: textColor,
    fontSize: Math.min(width * 0.08, 60), // Responsive font size
    textAlign: "right",
    lineHeight: "1.5",
    textShadow: "2px 2px 0px rgba(0,0,0,0.1)",
    transition: "none",
  };

  const labelStyle: React.CSSProperties = {
    color: textColor,
    fontSize: Math.min(width * 0.04, 30),
    textAlign: "left",
    opacity: 0.8,
    marginBottom: "10px",
    textTransform: "uppercase",
  };

  // Arrow indicator style
  const cursorStyle: React.CSSProperties = {
    width: 0,
    height: 0,
    borderLeft: "10px solid transparent",
    borderRight: "10px solid transparent",
    borderTop: `15px solid ${borderColor}`,
    position: "absolute",
    bottom: "20px",
    right: "20px",
    opacity: showCursor ? cursorOpacity : 0,
  };

  return (
    <AbsoluteFill style={containerStyle}>
      <div style={boxStyle}>
        <div style={labelStyle}>Total Amount</div>
        <div style={textStyle}>
          {currencySymbol}{displayCount}
        </div>
        {/* Blinking "Next" Cursor */}
        <div style={cursorStyle} />
      </div>
    </AbsoluteFill>
  );
};

export default PokemonCounter;